#include "../audio_script.h"
#include <cstdio>
#include <cstdlib>
using namespace Snatcher;
namespace {unsigned checks;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"Script audio: %s\n",why);std::exit(1);}}}
int main(){std::string error;ScriptAudioWait wait;for(unsigned queue:{19u,25u}){unsigned limit=queue==19?2700:600;check(wait.start(queue,error),"start source cache wait");for(unsigned n=1;n<limit;++n)check(wait.tick(79,60,kScriptCdUnknown,error)==kScriptAudioWaitPending&&wait.state().remaining==limit-n,"nonzero command cache retains wait despite renderer completion");check(wait.tick(79,60,kScriptCdUnknown,error)==kScriptAudioWaitFinished&&!wait.state().remaining,"exact bounded source countdown includes initial call");check(wait.start(queue,error)&&wait.tick(queue==19?0:79,queue==25?0:60,kScriptCdUnknown,error)==kScriptAudioWaitFinished,"matching source cache clear releases wait immediately");}
 check(wait.start(11,error),"start CD pause wait");auto before=wait.state();check(wait.tick(0,0,kScriptCdUnknown,error)==kScriptAudioWaitError&&wait.state().active&&wait.state().remaining==before.remaining,"unknown CD ownership fails without changing wait");for(unsigned n=0;n<4000;++n)check(wait.tick(0,0,kScriptCdPlaying,error)==kScriptAudioWaitPending,"CD wait has no invented timeout");check(wait.tick(0,0,kScriptCdPaused,error)==kScriptAudioWaitFinished,"CD paused finishes source predicate");check(wait.start(11,error)&&wait.tick(0,0,kScriptCdIdle,error)==kScriptAudioWaitFinished,"CD idle finishes source predicate");check(wait.start(19,error),"save source wait");for(unsigned n=0;n<123;++n)wait.tick(79,60,kScriptCdUnknown,error);ScriptAudioWait restored;check(restored.restore(wait.state(),error),"restore countdown state");for(unsigned n=0;n<2600;++n)check(wait.tick(79,60,kScriptCdUnknown,error)==restored.tick(79,60,kScriptCdUnknown,error)&&wait.state().remaining==restored.state().remaining,"saved countdown exact continuation");auto bad=wait.state();bad.active=true;bad.remaining=2701;check(!restored.restore(bad,error),"impossible countdown rejected");check(!wait.start(14,error),"CD play is not a wait-family shortcut");std::printf("Script audio wait: %u checks,0 failures\n",checks);return 0;}
